import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './CustomerDashboard.css';

interface Order {
  id: string;
  items: string[];
  amount: number;
  status: 'ready_to_pickup' | 'delivered' | 'in_progress';
  orderDate: string;
}

interface UserProfile {
  email: string;
  username: string;
  role: string;
  mobile: string;
  garageName?: string;
  registrationNumber?: string;
}

const CustomerDashboard: React.FC = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const navigate = useNavigate();

  // Hardcoded previous orders for demo
  const [orders] = useState<Order[]>([
    {
      id: 'ORD-001',
      items: ['Brake Pads', 'Engine Oil Filter'],
      amount: 12550.00,
      status: 'delivered',
      orderDate: '2025-09-25'
    },
    {
      id: 'ORD-002',
      items: ['Headlight Bulb', 'Windshield Wipers'],
      amount: 7899.00,
      status: 'ready_to_pickup',
      orderDate: '2025-09-28'
    },
    {
      id: 'ORD-003',
      items: ['Air Filter', 'Spark Plugs', 'Oil Change Kit'],
      amount: 18925.00,
      status: 'in_progress',
      orderDate: '2025-09-29'
    }
  ]);

  useEffect(() => {
    const currentUser = localStorage.getItem('currentUser');
    if (currentUser) {
      setUser(JSON.parse(currentUser));
    } else {
      navigate('/');
    }
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('currentUser');
    navigate('/');
  };

  const handleNewOrder = () => {
    navigate('/shop');
  };

  const getStatusBadge = (status: string) => {
    const statusMap = {
      'ready_to_pickup': { text: 'Ready to Pickup', class: 'status-ready' },
      'delivered': { text: 'Delivered', class: 'status-delivered' },
      'in_progress': { text: 'In Progress', class: 'status-progress' }
    };
    return statusMap[status as keyof typeof statusMap] || { text: status, class: 'status-default' };
  };

  if (!user) {
    return <div>Loading...</div>;
  }

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="header-content">
          <h1>Japan Lanka Enterprises</h1>
          <div className="header-actions">
            <span className="welcome-text">Welcome, {user.username}!</span>
            <button onClick={handleLogout} className="logout-btn">Logout</button>
          </div>
        </div>
      </header>

      <main className="dashboard-main">
        <div className="dashboard-grid">
          {/* Profile Section */}
          <section className="profile-section">
            <h2>Profile Details</h2>
            <div className="profile-card">
              <div className="profile-item">
                <label>Username:</label>
                <span>{user.username}</span>
              </div>
              <div className="profile-item">
                <label>Email:</label>
                <span>{user.email}</span>
              </div>
              <div className="profile-item">
                <label>Role:</label>
                <span className="role-badge">{user.role}</span>
              </div>
              {user.garageName && (
                <div className="profile-item">
                  <label>Garage:</label>
                  <span>{user.garageName}</span>
                </div>
              )}
              {user.registrationNumber && (
                <div className="profile-item">
                  <label>Registration:</label>
                  <span>{user.registrationNumber}</span>
                </div>
              )}
            </div>
          </section>

          {/* Orders Section */}
          <section className="orders-section">
            <h2>Previous Orders</h2>
            <div className="orders-list">
              {orders.length > 0 ? (
                orders.map((order) => (
                  <div key={order.id} className="order-card">
                    <div className="order-header">
                      <span className="order-id">#{order.id}</span>
                      <span className={`status-badge ${getStatusBadge(order.status).class}`}>
                        {getStatusBadge(order.status).text}
                      </span>
                    </div>
                    <div className="order-details">
                      <p className="order-items">
                        <strong>Items:</strong> {order.items.join(', ')}
                      </p>
                      <div className="order-meta">
                        <span className="order-amount">Rs. {order.amount.toFixed(2)}</span>
                        <span className="order-date">{new Date(order.orderDate).toLocaleDateString()}</span>
                      </div>
                    </div>
                  </div>
                ))
              ) : (
                <p className="no-orders">No previous orders found.</p>
              )}
            </div>
          </section>
        </div>

        {/* New Order Button */}
        <div className="new-order-section">
          <button onClick={handleNewOrder} className="new-order-btn">
            <span className="btn-icon">🛒</span>
            Place New Order
          </button>
        </div>
      </main>
    </div>
  );
};

export default CustomerDashboard;
